def host(s):
 p=urllib.parse.urlparse(s if "://" in s else "https://"+s)
 return (p.hostname or "").lower()
def req(path,method="GET",body=None,token=None):
 data=json.dumps(body).encode() if body is not None else None
 headers={"Accept":"application/json"}
 if data is not None: headers["Content-Type"]="application/json"
 if token: headers["Authorization"]="Bearer "+token
 r=urllib.request.Request(API+path,data=data,headers=headers,method=method)
 try:
  with urllib.request.urlopen(r,timeout=15) as response: return json.load(response)
 except urllib.error.HTTPError as e: fail("Mail.tm returned HTTP "+str(e.code))
 except (urllib.error.URLError,TimeoutError) as e: fail("Mail.tm unavailable: "+type(e).__name__)
def save(box):
 STATE.mkdir(parents=True,exist_ok=True,mode=0o700);os.chmod(STATE,0o700)
