 slug=re.sub(r"[^a-z0-9]+","-",host(site)).strip("-")[:20] or "test"
 email="test-"+slug+"-"+secrets.token_hex(5)+"@"+available[0];password=secrets.token_urlsafe(32)
 req("/accounts","POST",{"address":email,"password":password})
