 out({"login_type":"fresh_disposable_inbox","email":email,"mailbox_id":ident,"provider":"https://mail.tm","sticky_proxy":proxy,"note":"Short-lived tests only. Use list_mail/read_mail for verification."})
def list_mail(a):
