 sender=str(a.get("expected_sender") or "").lower()
 if sender: messages=[m for m in messages if sender in (m.get("from") or {}).get("address","").lower()]
 out({"email":box["address"],"sticky_proxy":box.get("sticky_proxy"),"messages":[{"id":m.get("id"),"from":(m.get("from") or {}).get("address"),"subject":m.get("subject"),"intro":str(m.get("intro") or "")[:300],"created_at":m.get("createdAt")} for m in messages[:10]]})
def read_mail(a):
